"use client";

import { useEffect, useState } from "react";

/** ORYVANTH — isolated silver emblem on a pure black field. */
const EMBLEM = "data:image/webp;base64,";

type CivilizationFunction = {
  id: string;
  name: string;
  purpose: string;
  foundations: string;
};

const CIVILIZATION_FUNCTIONS: readonly CivilizationFunction[] = [
  { id: "01", name: "Energy", purpose: "Sustain reliable power across changing conditions.", foundations: "Generation · Storage · Distribution · Recovery" },
  { id: "02", name: "Water", purpose: "Secure and regenerate usable water.", foundations: "Acquisition · Purification · Recycling · Monitoring" },
  { id: "03", name: "Food", purpose: "Maintain resilient nutrition and production.", foundations: "Cultivation · Nutrients · Preservation · Reserves" },
  { id: "04", name: "Habitat", purpose: "Provide safe environments for enduring life.", foundations: "Shelter · Atmosphere · Thermal control · Protection" },
  { id: "05", name: "Health", purpose: "Protect physical and psychological well-being.", foundations: "Prevention · Care · Diagnostics · Public health" },
  { id: "06", name: "Manufacturing", purpose: "Build, maintain and repair essential systems.", foundations: "Materials · Fabrication · Maintenance · Quality" },
  { id: "07", name: "Logistics", purpose: "Move and allocate critical resources.", foundations: "Transport · Inventory · Routing · Redundancy" },
  { id: "08", name: "Communications", purpose: "Keep people and systems connected.", foundations: "Networks · Protocols · Resilience · Security" },
  { id: "09", name: "Knowledge", purpose: "Preserve discovery and enable correction.", foundations: "Research · Education · Evidence · Memory" },
  { id: "10", name: "Coordination", purpose: "Coordinate decisions without removing human agency.", foundations: "Planning · Automation · Oversight · Accountability" },
  { id: "11", name: "Governance", purpose: "Make power accountable and decisions revisable.", foundations: "Rights · Rules · Audit · Appeal" },
  { id: "12", name: "Recovery", purpose: "Restore essential functions after disruption.", foundations: "Detection · Isolation · Repair · Adaptation" },
];

export default function OryvanthConstructionSystem() {
  const [reducedMotion, setReducedMotion] = useState(false);
  const [pulse, setPulse] = useState(0);
  const [expanded, setExpanded] = useState(false);
  const [selected, setSelected] = useState<string | null>(null);

  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  const selectedFunction = CIVILIZATION_FUNCTIONS.find((item) => item.id === selected);

  return (
    <div className={`ory-life ${expanded ? "is-awake" : ""}`} aria-label="ORYVANTH living civilization">
      <button
        type="button"
        className={`ory-life__being ${reducedMotion ? "is-still" : ""}`}
        aria-label={expanded ? "Hide civilization functions" : "Reveal civilization functions"}
        aria-expanded={expanded}
        aria-controls="ory-civilization-functions"
        onClick={() => {
          setPulse((value) => value + 1);
          setExpanded((value) => !value);
        }}
      >
        <span className="ory-life__emblem" style={{ backgroundImage: `url("${EMBLEM}")` }} aria-hidden="true" />
        <span key={pulse} className="ory-life__ripple" aria-hidden="true" />
      </button>

      <div id="ory-civilization-functions" className="ory-life__reveal" hidden={!expanded}>
        <div className="ory-life__intro">
          <span className="ory-life__eyebrow">ORYVANTH CIVILIZATION</span>
          <h2>Foundations of a living civilization</h2>
        </div>
        <div className="ory-life__grid" aria-label="Civilization functions">
          {CIVILIZATION_FUNCTIONS.map((item) => (
            <button
              type="button"
              key={item.id}
              className={`ory-life__node ${selected === item.id ? "is-selected" : ""}`}
              aria-pressed={selected === item.id}
              onClick={() => setSelected((value) => value === item.id ? null : item.id)}
            >
              <span className="ory-life__number">{item.id}</span>
              <span className="ory-life__name">{item.name}</span>
              <span className="ory-life__node-mark" aria-hidden="true" />
            </button>
          ))}
        </div>
        {selectedFunction && (
          <section className="ory-life__detail" aria-live="polite" aria-label={`${selectedFunction.name} details`}>
            <span className="ory-life__eyebrow">CIVILIZATION FUNCTION · {selectedFunction.id}</span>
            <h3>{selectedFunction.name}</h3>
            <p>{selectedFunction.purpose}</p>
            <small>{selectedFunction.foundations}</small>
          </section>
        )}
      </div>

      <style jsx>{`
        .ory-life {
          position: relative;
          display: flex;
          flex-direction: column;
          align-items: center;
          justify-content: center;
          width: 100%;
          min-width: 0;
          min-height: clamp(340px, 68svh, 820px);
          padding: clamp(24px, 4vw, 60px) clamp(16px, 4vw, 50px);
          overflow: hidden;
          isolation: isolate;
          background: #000;
          color: rgba(255,255,255,.88);
          box-sizing: border-box;
        }
        .ory-life__being {
          position: relative;
          display: block;
          flex: 0 0 auto;
          width: min(67%, 490px);
          aspect-ratio: 605 / 575;
          padding: 0;
          margin: 0;
          border: 0;
          border-radius: 50%;
          background: transparent;
          cursor: pointer;
          -webkit-tap-highlight-color: transparent;
          touch-action: manipulation;
        }
        .ory-life__being:focus-visible,
        .ory-life__node:focus-visible {
          outline: 1px solid rgba(255,255,255,.75);
          outline-offset: 5px;
        }
        .ory-life__emblem {
          position: absolute;
          inset: 0;
          background-position: center;
          background-size: contain;
          background-repeat: no-repeat;
          transform-origin: 50% 50%;
          animation: ory-turn 180s linear infinite;
          pointer-events: none;
        }
        .ory-life__ripple {
          position: absolute;
          inset: 31%;
          border: 1px solid rgba(255,255,255,.35);
          border-radius: 50%;
          opacity: 0;
          pointer-events: none;
          animation: ory-ripple 1.4s ease-out both;
        }
        .ory-life__being.is-still .ory-life__emblem { animation: none; }
        .ory-life__reveal {
          width: min(100%, 950px);
          margin: clamp(8px, 2vw, 22px) auto 0;
          animation: ory-appear .65s ease-out both;
        }
        .ory-life__reveal[hidden] { display: none; }
        .ory-life__intro { text-align: center; margin: 0 auto clamp(24px, 3vw, 36px); }
        .ory-life__eyebrow {
          display: block;
          color: rgba(255,255,255,.4);
          font-size: 9px;
          font-weight: 600;
          letter-spacing: .22em;
        }
        .ory-life__intro h2 {
          margin: 15px 0 9px;
          font-size: clamp(20px, 3vw, 32px);
          font-weight: 300;
          letter-spacing: -.035em;
          line-height: 1.25;
        }
        .ory-life__intro p {
          margin: 0;
          color: rgba(255,255,255,.43);
          font-size: clamp(11px, 1.2vw, 13px);
          line-height: 1.7;
        }
        .ory-life__grid {
          display: grid;
          grid-template-columns: repeat(4, minmax(0, 1fr));
          gap: 10px;
        }
        .ory-life__node {
          display: flex;
          align-items: center;
          gap: 12px;
          min-width: 0;
          min-height: 70px;
          padding: 16px;
          text-align: left;
          border: 1px solid rgba(255,255,255,.09);
          border-radius: 15px;
          background: linear-gradient(145deg, rgba(255,255,255,.045), rgba(255,255,255,.012));
          color: rgba(255,255,255,.8);
          cursor: pointer;
          transition: border-color .25s ease, background .25s ease, transform .25s ease;
        }
        .ory-life__node:hover, .ory-life__node.is-selected {
          border-color: rgba(255,255,255,.3);
          background: rgba(255,255,255,.075);
        }
        .ory-life__node:active { transform: scale(.985); }
        .ory-life__number { font-size: 10px; color: rgba(255,255,255,.3); font-variant-numeric: tabular-nums; }
        .ory-life__name { flex: 1; min-width: 0; font-size: 12px; font-weight: 500; letter-spacing: .015em; overflow-wrap: anywhere; }
        .ory-life__node-mark { width: 4px; height: 4px; flex: 0 0 auto; border-radius: 50%; background: rgba(255,255,255,.36); }
        .ory-life__node.is-selected .ory-life__node-mark { background: #fff; box-shadow: 0 0 9px rgba(255,255,255,.5); }
        .ory-life__detail {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  width: 100%;
  margin-top: 14px;
  padding: clamp(20px, 3vw, 32px);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 18px;
  background: rgba(255,255,255,.035);
}

.ory-life__detail > * {
  width: 100%;
  text-align: center;
}
        .ory-life__detail h3 { margin: 12px 0 7px; font-size: 22px; font-weight: 400; }
        .ory-life__detail p { margin: 0 0 13px; font-size: 13px; color: rgba(255,255,255,.7); line-height: 1.7; }
        .ory-life__detail small { font-size: 11px; color: rgba(255,255,255,.4); line-height: 1.7; }
        @keyframes ory-turn { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes ory-ripple { from { transform: scale(.25); opacity: .65; } to { transform: scale(3); opacity: 0; } }
        @keyframes ory-appear { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
        @media (max-width: 700px) {
          .ory-life { min-height: clamp(310px, 58svh, 620px); padding: 24px 14px 36px; }
          .ory-life__being { width: min(82%, 420px); }
          .ory-life__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
          .ory-life__node { min-height: 62px; padding: 12px; gap: 9px; border-radius: 12px; }
          .ory-life__name { font-size: 11px; }
        }
        @media (prefers-reduced-motion: reduce) {
          .ory-life__emblem, .ory-life__ripple, .ory-life__reveal { animation: none !important; }
          .ory-life__node { transition: none; }
        }
      `}</style>
    </div>
  );
}
